function tr(k){return curLang==='en'||!T[k]?k:T[k][LI[curLang]]}
function fmtDate(d){try{return new Intl.DateTimeFormat(curLang,{day:'numeric',month:'long',year:'numeric'}).format(new Date(d+'T12:00:00'))}catch(e){return d}}
function renderShots(){
  var el=document.getElementById('shots'),hd=document.getElementById('shotsH');el.textContent='';el.hidden=!SHOTS.length;hd.hidden=!SHOTS.length;
  SHOTS.forEach(function(x){
    var cap=(x.title?x.title+(x.date?' \u2013 ':''):'')+(x.date?fmtDate(x.date):''),alt=(x.name?'Trustpilot: '+x.name+', 5/5':tr('Member reviews'))+(x.date?', '+fmtDate(x.date):'');
    var f=document.createElement('figure');f.className='shot';
    var b=document.createElement('button');b.setAttribute('aria-label',alt);b.setAttribute('data-err',tr('Image could not be loaded'));
    var i=document.createElement('img');i.loading='lazy';i.alt=alt;i.src=x.src;i.onerror=function(){f.classList.add('noimg')};
    b.appendChild(i);b.addEventListener('click',function(){if(f.classList.contains('noimg'))return;var lb=document.getElementById('lb');lb.querySelector('img').src=x.src;lb.querySelector('img').alt=alt;document.getElementById('lbcap').textContent=cap;if(lb.showModal)lb.showModal()});
    f.appendChild(b);
    if(cap){var c=document.createElement('figcaption'),t=document.createElement('b');t.textContent=cap;c.appendChild(t);f.appendChild(c)}
    el.appendChild(f);
  });
}
