var c=document.getElementById('stars');
if(c&&c.getContext){
  var x=c.getContext('2d'),W,H,S=[],shoot=null,vis=true,dpr=window.innerWidth<700?1:Math.min(window.devicePixelRatio||1,1.5),fr=0;
  function size(){W=c.clientWidth;H=c.clientHeight;c.width=W*dpr;c.height=H*dpr;x.setTransform(dpr,0,0,dpr,0,0);S=[];var n=Math.min(260,Math.round(W*H/(W<700?9000:5200)));for(var i=0;i<n;i++)S.push({x:Math.random()*W,y:Math.random()*H,r:Math.random()<.05?Math.random()*1.4+1.5:Math.random()*1.2+.3,p:Math.random()*6.28,s:Math.random()*.02+.006})}
  function draw(){
    if(!reduce&&(fr++&1)){if(vis)requestAnimationFrame(draw);return}
    x.clearRect(0,0,W,H);
    for(var i=0;i<S.length;i++){var s=S[i];s.p+=s.s*2;x.globalAlpha=.25+.55*(.5+.5*Math.sin(s.p));x.fillStyle=i%3===0?'#9CC8FF':(i%11===0?'#FFE3A0':'#fff');x.beginPath();x.arc(s.x,s.y,s.r,0,6.28);x.fill()}
    if(!shoot&&Math.random()<.008)shoot={x:Math.random()*W*.7+W*.3,y:Math.random()*H*.3,l:0};
    if(shoot){shoot.x-=13;shoot.y+=6;shoot.l+=2;var g=x.createLinearGradient(shoot.x,shoot.y,shoot.x+90,shoot.y-41);g.addColorStop(0,'rgba(190,225,255,.9)');g.addColorStop(1,'rgba(190,225,255,0)');x.globalAlpha=Math.max(0,1-shoot.l/60);x.strokeStyle=g;x.lineWidth=1.5;x.beginPath();x.moveTo(shoot.x,shoot.y);x.lineTo(shoot.x+90,shoot.y-41);x.stroke();if(shoot.l>60)shoot=null}
    x.globalAlpha=1;
    if(!reduce&&vis)requestAnimationFrame(draw);
  }
  size();draw();
  var rt;window.addEventListener('resize',function(){clearTimeout(rt);rt=setTimeout(function(){size();if(reduce)draw()},150)});
  if('IntersectionObserver' in window){new IntersectionObserver(function(es){var was=vis;vis=es[0].isIntersecting;if(vis&&!was&&!reduce)requestAnimationFrame(draw)}).observe(c)}
}
